import Foundation

struct ClipboardDiffStrings {
    let title: String, subtitle: String, legend: String, missing: String, tooLarge: String, loading: String, identical: String
    let before: String, after: String
    let previousChange: String, nextChange: String, pasteHint: String
    let formatJSON: String, invalidJSON: String, formattedTooLarge: String
    private let summaryFormat: String

    func summary(changed: Int, added: Int, removed: Int) -> String {
        let parts = String(format: summaryFormat, changed, added, removed).components(separatedBy: " · ")
        let summary = zip([changed, added, removed], parts)
            .compactMap { count, text in count > 0 ? text : nil }
            .joined(separator: " · ")
        return summary.isEmpty ? identical : summary
    }

