        switch language {
        case .enUS: return .init(title: "Clipboard diff", subtitle: "Compare the two latest saved text copies", legend: "− Before    + After", missing: "Paste or edit both texts to compare them automatically.", tooLarge: "Each copy must fit within 200 KB and 2,000 lines. Nothing was truncated.", loading: "Comparing…", identical: "No differences", before: "Before", after: "After", previousChange: "Previous change", nextChange: "Next change", pasteHint: "Paste text here", formatJSON: "Format JSON", invalidJSON: "Cannot format this JSON. Text unchanged.", formattedTooLarge: "Formatted JSON exceeds 200 KB or 2,000 lines. Text unchanged.", summaryFormat: "%d changed · +%d · −%d")
