        case .ru: return .init(title: "Сравнение буфера обмена", subtitle: "Сравнить две последние сохранённые копии текста", legend: "− До    + После", missing: "Вставьте или измените оба текста для автоматического сравнения.", tooLarge: "Каждая копия должна содержать не более 200 КБ и 2 000 строк. Ничего не обрезано.", loading: "Сравнение…", identical: "Различий нет", before: "До", after: "После", previousChange: "Предыдущее изменение", nextChange: "Следующее изменение", pasteHint: "Вставьте текст здесь", formatJSON: "Форматировать JSON", invalidJSON: "Не удалось отформатировать JSON. Текст не изменён.", formattedTooLarge: "После форматирования JSON превышает 200 КБ или 2 000 строк. Текст не изменён.", summaryFormat: "Изменено: %d · +%d · −%d")
